noncompliant.code:
# GCP Firewall rule
from googleapiclient import discovery

compute = discovery.build('compute', 'v1')

firewall_rule = {
    'name': 'allow-ssh',
    'allowed': [{
        'IPProtocol': 'tcp',
        'ports': ['22']
    }],
    'sourceRanges': ['0.0.0.0/0'],  # Noncompliant: allows access from anywhere
    'direction': 'INGRESS'
}

compliant.code:
# GCP Firewall rule with restricted source
from googleapiclient import discovery

compute = discovery.build('compute', 'v1')

firewall_rule = {
    'name': 'allow-ssh',
    'allowed': [{
        'IPProtocol': 'tcp',
        'ports': ['22']
    }],
    'sourceRanges': ['10.0.0.0/24'],  # Compliant: restricted to internal network
    'direction': 'INGRESS'
}
